940: function gapToLeaderSeconds(leader, progress, speed) {
941:   const history = leader.history;
942:   if (!history || history.length < 2) return 0;
943:   const first = history[0];
944:   const last = history[history.length - 1];
945:   if (progress >= last.p) return 0;
946:   if (progress < first.p) {
947:     // Before the leader's first sample (the grid): no elapsed race time yet.
948:     if (race.time < 600) return 0;
949:     const metres = (first.p - progress) * race.track.length;
950:     return metres / Math.max(24, speed);
951:   }
952:   // Binary search for the first timeline sample at or beyond this progress.
953:   let lo = 0, hi = history.length - 1;
954:   while (lo < hi) {
955:     const mid = (lo + hi) >> 1;
956:     if (history[mid].p >= progress) hi = mid; else lo = mid + 1;
957:   }
958:   const b = history[lo];
959:   const a = history[Math.max(0, lo - 1)];
960:   if (b === a) return Math.max(0, (race.time - b.t) / 1000);
961:   const f = clamp((progress - a.p) / Math.max(1e-6, b.p - a.p), 0, 1);
962:   const tAt = a.t + (b.t - a.t) * f;
963:   return Math.max(0, (race.time - tAt) / 1000);
964: }
