921: // Keep a short timeline of every car's race progress. Comparing the leader's
922: // timeline against a chaser's current progress gives the time gap you would
923: // see on an F1 timing tower, rather than a guessed distance/speed division.
924: function recordGapHistory() {
925:   if (!race || race.state !== 'racing') return;
926:   const now = race.time;
927:   const push = (history, progress) => {
928:     const last = history[history.length - 1];
929:     if (last && now - last.t < 90) return;
930:     history.push({ t: now, p: progress });
931:     if (history.length > 2600) history.splice(0, 400);
932:   };
933:   push(race.player.history, playerProgress());
934:   for (const a of race.ai) {
935:     const progress = a.finished ? TOTAL_LAPS : Math.min(TOTAL_LAPS, a.dist / race.track.length);
936:     push(a.history, progress);
937:   }
938: }
