const RACE_SETUP_DEFAULTS = { laps: 3, ai: 3 };
try {
  const savedLaps = Number(localStorage.getItem('apexink.laps'));
  const savedAI = Number(localStorage.getItem('apexink.ai'));
  if (Number.isInteger(savedLaps) && savedLaps >= 1 && savedLaps <= 10) dom.setupLaps.value = String(savedLaps);
  if (Number.isInteger(savedAI) && savedAI >= 0 && savedAI <= 9) dom.setupAI.value = String(savedAI);
} catch {}

function getRaceSetup() {
  const laps = Number(dom.setupLaps.value);
  const ai = Number(dom.setupAI.value);
  return {
    totalLaps: Number.isInteger(laps) ? clamp(laps, 1, 10) : RACE_SETUP_DEFAULTS.laps,
    aiCount: Number.isInteger(ai) ? clamp(ai, 0, 9) : RACE_SETUP_DEFAULTS.ai
  };
}

