942: // Keep a short timeline of every car's race progress. Comparing the leader's
943: // timeline against a chaser's current progress gives the time gap you would
944: // see on an F1 timing tower, rather than a guessed distance/speed division.
945: function recordGapHistory() {
946:   if (!race || race.state !== 'racing') return;
947:   const now = race.time;
948:   const push = (history, progress) => {
949:     const last = history[history.length - 1];
950:     if (last && now - last.t < 90) return;
951:     history.push({ t: now, p: progress });
952:     if (history.length > 2600) history.splice(0, 400);
953:   };
954:   push(race.player.history, playerProgress());
955:   for (const a of race.ai) {
956:     const progress = a.finished ? race.totalLaps : Math.min(race.totalLaps, a.dist / race.track.length);
957:     push(a.history, progress);
