961: function gapToLeaderSeconds(leader, progress, speed) {
962:   const history = leader.history;
963:   if (!history || history.length < 2) return 0;
964:   const first = history[0];
965:   const last = history[history.length - 1];
966:   if (progress >= last.p) return 0;
967:   if (progress < first.p) {
968:     // Before the leader's first sample (the grid): no elapsed race time yet.
969:     if (race.time < 600) return 0;
970:     const metres = (first.p - progress) * race.track.length;
971:     return metres / Math.max(24, speed);
972:   }
973:   // Binary search for the first timeline sample at or beyond this progress.
974:   let lo = 0, hi = history.length - 1;
975:   while (lo < hi) {
976:     const mid = (lo + hi) >> 1;
977:     if (history[mid].p >= progress) hi = mid; else lo = mid + 1;
978:   }
979:   const b = history[lo];
980:   const a = history[Math.max(0, lo - 1)];
981:   if (b === a) return Math.max(0, (race.time - b.t) / 1000);
982:   const f = clamp((progress - a.p) / Math.max(1e-6, b.p - a.p), 0, 1);
983:   const tAt = a.t + (b.t - a.t) * f;
984:   return Math.max(0, (race.time - tAt) / 1000);
985: }
